/*
 * mod-unbound: Bulletin Board weekly picks.
 *
 * The board's quests are generated by tools/bulletin_board.py (data/sql/db-world/unbound_bulletin_board.sql).
 * Dailies rotate through the core's quest pools; this file picks the weeklies: for each tier (Normal,
 * Heroic, Mythic) one dungeon and one raid, never the same dungeon (raid) for two tiers in the same week,
 * and one elite bounty (an elite camp in the open world), never the same as the week before.
 * The picks are world states (index + 1 into DUNGEONS / RAIDS in the tool), and each weekly quest is only
 * available while its world state matches (conditions). They are picked again at every weekly reset
 * (the core's next-reset time, world state 20002, changes) and on startup if they've never been picked.
 *
 * The weekly quests ask for the boss's normal entry in every tier: the core gives kill credit for a creature's
 * normal entry even when its heroic copy was killed (Player::KilledMonsterCredit compares GetEntry()). So the
 * mode is checked here (OnPlayerPassedQuestKilledMonsterCredit, which also gets the template entry that was
 * actually killed): a Normal quest only counts a Normal kill, a Heroic or Mythic quest only a Heroic one.
 *
 * GM commands: .bulletinboard show (this week's picks), .bulletinboard reroll (pick again now).
 */

#include "Chat.h"
#include "Player.h"
#include "QuestDef.h"
#include "CommandScript.h"
#include "Random.h"
#include "ScriptMgr.h"
#include "WorldState.h"
#include "WorldStateDefines.h"

#include <algorithm>
#include <array>
#include <numeric>
#include <string>
#include <vector>

using namespace Acore::ChatCommands;

namespace
{
    // Keep in sync with tools/bulletin_board.py (WS_DUNGEON, WS_RAID, DUNGEONS, RAIDS)
    constexpr std::array<uint32, 3> WS_DUNGEON = { 920001, 920002, 920003 };   // Normal, Heroic, Mythic
    constexpr std::array<uint32, 3> WS_RAID = { 920004, 920005, 920006 };
    constexpr uint32 WS_ELITE = 920007;         // this week's elite bounty
    constexpr uint32 WS_PICKED_FOR = 920009;    // the weekly reset time the picks were made for
    constexpr uint32 DUNGEON_COUNT = 26;
    constexpr uint32 RAID_COUNT = 7;
    constexpr uint32 ELITE_COUNT = 12;
    constexpr std::array<char const*, 3> TIERS = { "Normal", "Heroic", "Mythic" };

    constexpr uint32 CHECK_INTERVAL = 60 * IN_MILLISECONDS;

    // Weekly quest ids (tools/bulletin_board.py, DUNGEON_TIERS / RAID_TIERS): 9201xx Normal dungeon, 9202xx
    // Heroic, 9203xx Mythic, 9204xx Normal raid, 9205xx Heroic, 9206xx Mythic.
    constexpr uint32 WEEKLY_QUEST_FIRST = 920100;
    constexpr uint32 WEEKLY_QUEST_LAST = 920699;

    // A different place (1..count) for each tier.
    void PickDistinct(std::array<uint32, 3> const& states, uint32 count)
    {
        std::vector<uint32> places(count);
        std::iota(places.begin(), places.end(), 1);
        Acore::Containers::RandomShuffle(places);
        for (size_t tier = 0; tier < states.size(); ++tier)
            sWorldState->setWorldState(states[tier], tier < places.size() ? places[tier] : 0);
    }

    // Any bounty but last week's.
    void PickElite()
    {
        uint32 const last = uint32(sWorldState->getWorldState(WS_ELITE));
        uint32 pick = urand(1, ELITE_COUNT - (last ? 1 : 0));
        if (last && pick >= last)
            ++pick;
        sWorldState->setWorldState(WS_ELITE, pick);
    }

    void PickWeek()
    {
        PickDistinct(WS_DUNGEON, DUNGEON_COUNT);
        PickDistinct(WS_RAID, RAID_COUNT);
        PickElite();
        sWorldState->setWorldState(WS_PICKED_FOR, sWorldState->getWorldState(WORLD_STATE_CUSTOM_WEEKLY_QUEST_RESET_TIME));
    }

    bool NeedsPick()
    {
        if (!sWorldState->getWorldState(WS_DUNGEON[0]) || !sWorldState->getWorldState(WS_RAID[0]))
            return true;
        uint64 const reset = sWorldState->getWorldState(WORLD_STATE_CUSTOM_WEEKLY_QUEST_RESET_TIME);
        // the stored value is 32-bit (worldstates.value)
        return reset && uint32(reset) != uint32(sWorldState->getWorldState(WS_PICKED_FOR));
    }

    void Check()
    {
        if (NeedsPick())
            PickWeek();
        else if (!sWorldState->getWorldState(WS_ELITE))
            PickElite();    // added after this week's dungeons and raids were picked: keep those
    }
}

class unbound_bulletin_board_world : public WorldScript
{
public:
    unbound_bulletin_board_world() : WorldScript("unbound_bulletin_board_world", {
        WORLDHOOK_ON_STARTUP,
        WORLDHOOK_ON_UPDATE
    }) { }

    void OnStartup() override
    {
        Check();
    }

    void OnUpdate(uint32 diff) override
    {
        _timer += diff;
        if (_timer < CHECK_INTERVAL)
            return;
        _timer = 0;
        Check();
    }

private:
    uint32 _timer = 0;
};

// The mode of a weekly quest's boss kill: entry is the killed creature's template (its heroic copy in Heroic),
// realEntry the normal entry the quest asks for.
class unbound_bulletin_board_player : public PlayerScript
{
public:
    unbound_bulletin_board_player() : PlayerScript("unbound_bulletin_board_player", {
        PLAYERHOOK_PASSED_QUEST_KILLED_MONSTER_CREDIT
    }) { }

    bool OnPlayerPassedQuestKilledMonsterCredit(Player* /*player*/, Quest const* quest, uint32 entry, uint32 realEntry,
        ObjectGuid /*guid*/) override
    {
        uint32 const id = quest->GetQuestId();
        if (id < WEEKLY_QUEST_FIRST || id > WEEKLY_QUEST_LAST)
            return true;

        uint32 const tier = (id - WEEKLY_QUEST_FIRST) / 100 % 3;   // 0 Normal, 1 Heroic, 2 Mythic
        bool const killedHeroic = entry != realEntry;
        return tier == 0 ? !killedHeroic : killedHeroic;
    }
};

class unbound_bulletin_board_commands : public CommandScript
{
public:
    unbound_bulletin_board_commands() : CommandScript("unbound_bulletin_board_commands") { }

    ChatCommandTable GetCommands() const override
    {
        static ChatCommandTable boardTable =
        {
            { "show",   HandleShow,   SEC_GAMEMASTER, Console::Yes },
            { "reroll", HandleReroll, SEC_GAMEMASTER, Console::Yes },
        };
        static ChatCommandTable commandTable =
        {
            { "bulletinboard", boardTable },
        };
        return commandTable;
    }

    static bool HandleShow(ChatHandler* handler)
    {
        for (size_t tier = 0; tier < TIERS.size(); ++tier)
            handler->PSendSysMessage("{} dungeon: {} (quest {}), {} raid: {} (quest {})", TIERS[tier],
                sWorldState->getWorldState(WS_DUNGEON[tier]), 920100 + tier * 100 + sWorldState->getWorldState(WS_DUNGEON[tier]),
                TIERS[tier], sWorldState->getWorldState(WS_RAID[tier]), 920400 + tier * 100 + sWorldState->getWorldState(WS_RAID[tier]));
        handler->PSendSysMessage("Elite bounty: {} (quest {})", sWorldState->getWorldState(WS_ELITE),
            920900 + sWorldState->getWorldState(WS_ELITE));
        handler->SendSysMessage("Numbers are positions in DUNGEONS / RAIDS / ELITE_QUESTS in tools/bulletin_board.py. Heroic raids and "
                                "Mythic have no quests yet.");
        return true;
    }

    static bool HandleReroll(ChatHandler* handler)
    {
        PickWeek();
        handler->SendSysMessage("Bulletin Board: this week's dungeons and raids were picked again.");
        return HandleShow(handler);
    }
};

void AddSC_unbound_bulletin_board()
{
    new unbound_bulletin_board_world();
    new unbound_bulletin_board_player();
    new unbound_bulletin_board_commands();
}
